pub fn n_smallest(items: Vec<i32>, n: usize) -> Vec<i32> {
    let mut sorted = items;
    sorted.sort();
    sorted[..n].to_vec()
}

fn main() {
    println!("{:?}", n_smallest(vec![5, 1, 4, 2, 3], 3));
    println!("{:?}", n_smallest(vec![5, 1], 10));
    println!("{:?}", n_smallest(vec![], 0));
}
